module TopModule (
    input  logic       clk,
    input  logic       x,
    input  logic [2:0] y,
    output logic       Y0,
    output logic       z
);

    // Suppress unused warning for clk
    wire _unused = clk;

    logic [2:0] Y_next;

    always_comb begin
        case (y)
            3'b000: begin
                z = 1'b0;
                Y_next = x ? 3'b001 : 3'b000;
            end
            3'b001: begin
                z = 1'b0;
                Y_next = x ? 3'b100 : 3'b001;
            end
            3'b010: begin
                z = 1'b0;
                Y_next = x ? 3'b001 : 3'b010;
            end
            3'b011: begin
                z = 1'b1;
                Y_next = x ? 3'b010 : 3'b001;
            end
            3'b100: begin
                z = 1'b1;
                Y_next = x ? 3'b100 : 3'b011;
            end
            default: begin
                z = 1'b0;
                Y_next = 3'b000;
            end
        endcase
    end

    assign Y0 = Y_next[0];

endmodule

