module tb_TopModule;
    reg clk;
    reg x;
    reg [2:0] y;
    wire Y0;
    wire z;

    TopModule uut (
        .clk(clk),
        .x(x),
        .y(y),
        .Y0(Y0),
        .z(z)
    );

    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        // Test all states and inputs
        integer state, inp;
        reg [2:0] expected_Y;
        reg expected_z;
        reg [2:0] test_y;
        reg test_x;

        for (state = 0; state < 5; state = state + 1) begin
            for (inp = 0; inp < 2; inp = inp + 1) begin
                y = state[2:0];
                x = inp[0];
                #10;

                // Determine expected values based on spec table independently
                case (y)
                    3'b000: begin
                        expected_z = 0;
                        expected_Y = x ? 3'b001 : 3'b000;
                    end
                    3'b001: begin
                        expected_z = 0;
                        expected_Y = x ? 3'b100 : 3'b001;
                    end
                    3'b010: begin
                        expected_z = 0;
                        expected_Y = x ? 3'b001 : 3'b010;
                    end
                    3'b011: begin
                        expected_z = 1;
                        expected_Y = x ? 3'b010 : 3'b001;
                    end
                    3'b100: begin
                        expected_z = 1;
                        expected_Y = x ? 3'b100 : 3'b011;
                    end
                    default: begin
                        expected_z = 0;
                        expected_Y = 3'b000;
                    end
                endcase

                if (z !== expected_z || Y0 !== expected_Y[0]) begin
                    $display("SELFFAIL: y=%b x=%b | got z=%b Y0=%b | expected z=%b Y0=%b", 
                             y, x, z, Y0, expected_z, expected_Y[0]);
                    $finish;
                end
            end
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
